import type { Snippet } from 'svelte'

/**
 * The states fixture: a Svelte member's `*.states.svelte`, generated by
 * `pnpm shells` from the member's description (`packages/shells/src/members/`).
 *
 * The entries carry the React fixture's names, so a contract's `when <state>`
 * names the same entry in every shell. `render` is a snippet that takes the
 * props the conformance runner sets on the member (a probe name, a spy in a
 * handler), spread over the fixture's own.
 */
export type Overrides = Readonly<Record<string, unknown>>

export interface StateEntry {
  name: string
  render: Snippet<[Overrides]>
  /** Attributes the rendered root must carry. `null` asserts absence. */
  expect?: Record<string, string | null>
  /** The entry renders nothing at all, by design. */
  rendersNothing?: true
}

export interface ComponentStates {
  component: string
  entries: StateEntry[]
}
